24	export const ExperimentPageSideNavSection = ({
25	  sectionKey,
26	  activeTab,
27	  items,
28	}: {
29	  sectionKey: ExperimentPageSideNavSectionKey;
30	  activeTab: ExperimentPageTabName;
31	  items: ExperimentPageSideNavItem[];
32	}) => {
33	  const { theme } = useDesignSystemTheme();
34	  const { experimentId } = useParams();
35	  const { search } = useLocation();
36	  const logTelemetryEvent = useLogTelemetryEvent();
37	  const viewId = useMemo(() => uuidv4(), []);
38	
39	  invariant(experimentId, 'Experiment ID must be defined');
40	
41	  // NOTE: everything with `className={COLLAPSED_CLASS_NAME}` is hidden at
42	  // large screen sizes (browser's XL breakpoint). The`display` property is
43	  // controlled via media query in the parent component. This is why there are
44	  // seemingly duplicate elements in the code below.
45	  return (
46	    <div css={{ display: 'flex', flexDirection: 'column', marginBottom: theme.spacing.sm + theme.spacing.xs }}>
47	      {sectionKey !== 'top-level' && (
48	        <div
49	          css={{
50	            display: 'flex',
51	            marginBottom: theme.spacing.xs,
52	            position: 'relative',
53	            height: theme.typography.lineHeightBase,
54	          }}
55	        >
56	          <div
57	            className={COLLAPSED_CLASS_NAME}
58	            css={{
59	              border: 'none',
60	              borderBottom: `1px solid ${theme.colors.border}`,
61	              width: '100%',
62	              position: 'absolute',
63	              bottom: '50%',
64	            }}
65	          />
66	          <Typography.Text className={FULL_WIDTH_CLASS_NAME} size="sm" color="secondary">
67	            {getExperimentPageSideNavSectionLabel(sectionKey as ExperimentPageSideNavSectionKey, items)}
68	          </Typography.Text>
69	        </div>
70	      )}
71	      {items.map((item) => {
72	        // SingleChatSession is a special case because it's a nested tab
73	        const isActive =
74	          activeTab === ExperimentPageTabName.SingleChatSession
75	            ? item.tabName === ExperimentPageTabName.ChatSessions
76	            : activeTab === item.tabName;
77	
78	        const preserveQueryParams = isTracesRelatedTab(activeTab) && isTracesRelatedTab(item.tabName);
79	
80	        return (
81	          <Link
82	            key={`${sectionKey}-${item.tabName}`}
83	            to={{
84	              pathname: Routes.getExperimentPageTabRoute(experimentId, item.tabName),
85	              search: preserveQueryParams ? search : undefined,
86	            }}
87	            onClick={() =>
88	              logTelemetryEvent({
89	                componentId: item.componentId,
90	                componentViewId: viewId,
91	                componentType: DesignSystemEventProviderComponentTypes.TypographyLink,
92	                componentSubType: null,
93	                eventType: DesignSystemEventProviderAnalyticsEventTypes.OnClick,
94	              })
95	            }
96	          >
97	            <div
98	              css={{
99	                display: 'flex',
100	                alignItems: 'center',
101	                gap: theme.spacing.sm,
102	                padding: `${theme.spacing.xs}px ${theme.spacing.sm}px`,
103	                borderRadius: theme.borders.borderRadiusSm,
104	                cursor: 'pointer',
105	                backgroundColor: isActive ? theme.colors.actionDefaultBackgroundHover : undefined,
106	                color: isActive ? theme.colors.actionDefaultIconHover : theme.colors.actionDefaultIconDefault,
107	                height: theme.typography.lineHeightBase,
108	                boxSizing: 'content-box',
109	                ':hover': { backgroundColor: theme.colors.actionDefaultBackgroundHover },
110	              }}
111	            >
112	              <Tooltip
113	                componentId="codegen_no_dynamic_mlflow_web_js_src_experiment_tracking_pages_experiment_page_tabs_side_nav_experimentpagesidenavsection_93"
114	                content={item.label}
115	                side="right"
116	                delayDuration={0}
117	              >
118	                <span className={COLLAPSED_CLASS_NAME}>{item.icon}</span>
119	              </Tooltip>
120	              <span className={FULL_WIDTH_CLASS_NAME}>{item.icon}</span>
121	              <Typography.Text className={FULL_WIDTH_CLASS_NAME} bold={isActive} color="primary">
122	                {item.label}
123	              </Typography.Text>
124	            </div>
125	          </Link>
126	        );
127	      })}
128	    </div>
129	  );
130	};
