1	import { createContext, useCallback, useContext, useEffect, useMemo } from 'react';
2	
3	import { useLocalStorage } from '@databricks/web-shared/hooks';
4	
5	import { useParams, useSearchParams } from '../../common/utils/RoutingUtils';
6	import { useMonitoringConfig } from './useMonitoringConfig';
7	import { shouldEnableTracesTableStatePersistence } from '@databricks/web-shared/model-trace-explorer';
8	
9	export const START_TIME_LABEL_QUERY_PARAM_KEY = 'startTimeLabel';
10	const START_TIME_QUERY_PARAM_KEY = 'startTime';
11	const END_TIME_QUERY_PARAM_KEY = 'endTime';
12	
13	export type START_TIME_LABEL =
14	  | 'LAST_HOUR'
15	  | 'LAST_24_HOURS'
16	  | 'LAST_7_DAYS'
17	  | 'LAST_30_DAYS'
18	  | 'LAST_YEAR'
19	  | 'ALL'
20	  | 'CUSTOM';
21	export const DEFAULT_START_TIME_LABEL: START_TIME_LABEL = 'LAST_7_DAYS';
22	
23	export interface MonitoringFilters {
24	  startTimeLabel?: START_TIME_LABEL;
25	  startTime?: string;
26	  endTime?: string;
27	}
28	
29	export const MonitoringFiltersUpdateContext = createContext<{
30	  params: MonitoringFilters;
31	  setParams: (params: MonitoringFilters, replace?: boolean) => void;
32	  disableAutomaticInitialization?: boolean;
33	} | null>(null);
34	
35	/**
36	 * Query param-powered hook that returns the monitoring filters from the URL.
37	 * Uses MonitoringFiltersUpdateContext if provided, otherwise falls back to URL search params.
38	 */
39	export const useMonitoringFilters = ({
40	  persist = false,
41	  loadPersistedValues = false,
42	}: { persist?: boolean; loadPersistedValues?: boolean } = {}) => {
43	  const { experimentId: persistKey } = useParams<{ experimentId: string }>();
44	  const monitoringConfig = useMonitoringConfig();
45	  const context = useContext(MonitoringFiltersUpdateContext);
46	  const [searchParams, setSearchParams] = useSearchParams();
47	
48	  const [localStorageFilters, persistLocalStorageFilters] = useLocalStorage<MonitoringFilters | undefined>({
49	    initialValue: undefined,
50	    key: `traces_useMonitoringFilters_${persistKey}`,
51	    version: 1,
52	  });
53	
54	  const isEmptySearchParams = useMemo(() => !searchParams.get(START_TIME_LABEL_QUERY_PARAM_KEY), [searchParams]);
55	
56	  const startTimeLabel =
57	    (searchParams.get(START_TIME_LABEL_QUERY_PARAM_KEY) as START_TIME_LABEL | undefined) || DEFAULT_START_TIME_LABEL;
58	  let startTime = searchParams.get(START_TIME_QUERY_PARAM_KEY) || undefined;
59	  let endTime = searchParams.get(END_TIME_QUERY_PARAM_KEY) ?? undefined;
60	  if (startTimeLabel !== 'CUSTOM') {
61	    const absoluteStartEndTime = getAbsoluteStartEndTime(monitoringConfig.dateNow, { startTimeLabel });
62	    startTime = absoluteStartEndTime.startTime;
63	    endTime = absoluteStartEndTime.endTime;
64	  }
65	
66	  const monitoringFilters = useMemo<MonitoringFilters>(
67	    () => ({
68	      startTimeLabel,
69	      startTime,
70	      endTime,
71	    }),
72	    [startTimeLabel, startTime, endTime],
73	  );
74	
75	  const setMonitoringFilters = useCallback(
76	    (monitoringFilters: MonitoringFilters | undefined, replace = false) => {
77	      if (persist) {
78	        persistLocalStorageFilters(monitoringFilters);
79	      }
80	      setSearchParams(
81	        (params) => {
82	          if (monitoringFilters?.startTime === undefined) {
83	            params.delete(START_TIME_QUERY_PARAM_KEY);
84	          } else if (monitoringFilters.startTimeLabel === 'CUSTOM') {
85	            params.set(START_TIME_QUERY_PARAM_KEY, monitoringFilters.startTime);
86	          }
87	          if (monitoringFilters?.endTime === undefined) {
88	            params.delete(END_TIME_QUERY_PARAM_KEY);
89	          } else if (monitoringFilters.startTimeLabel === 'CUSTOM') {
90	            params.set(END_TIME_QUERY_PARAM_KEY, monitoringFilters.endTime);
91	          }
92	          if (monitoringFilters?.startTimeLabel === undefined) {
93	            params.delete(START_TIME_LABEL_QUERY_PARAM_KEY);
94	          } else {
95	            params.set(START_TIME_LABEL_QUERY_PARAM_KEY, monitoringFilters.startTimeLabel);
96	          }
97	          return params;
98	        },
99	        { replace },
100	      );
101	    },
102	    [setSearchParams, persistLocalStorageFilters, persist],
103	  );
104	
105	  const disableAutomaticInitialization = Boolean(
106	    searchParams.has(START_TIME_LABEL_QUERY_PARAM_KEY) || context?.disableAutomaticInitialization,
107	  );
108	
109	  useEffect(() => {
110	    if (isEmptySearchParams && loadPersistedValues && localStorageFilters) {
111	      setMonitoringFilters(localStorageFilters, true);
112	    }
113	    // Rehydrate from local storage only once
114	    // eslint-disable-next-line react-hooks/exhaustive-deps
115	  }, [loadPersistedValues]);
116	
117	  return [monitoringFilters, setMonitoringFilters, disableAutomaticInitialization] as const;
118	};
119	
120	export const useMonitoringFiltersTimeRange = () => {
121	  const [monitoringFilters] = useMonitoringFilters({
122	    loadPersistedValues: shouldEnableTracesTableStatePersistence(),
123	  });
124	
125	  return useMemo(() => {
126	    const { startTime, endTime } = monitoringFilters;
127	    return {
128	      startTime: startTime ? new Date(startTime).getTime().toString() : undefined,
129	      endTime: endTime ? new Date(endTime).getTime().toString() : undefined,
130	    };
131	  }, [monitoringFilters]);
132	};
133	
134	export function getAbsoluteStartEndTime(
135	  dateNow: Date,
136	  monitoringFilters: MonitoringFilters,
137	): {
138	  startTime: string | undefined;
139	  endTime: string | undefined;
140	} {
141	  if (monitoringFilters.startTimeLabel && monitoringFilters.startTimeLabel !== 'CUSTOM') {
142	    return startTimeLabelToStartEndTime(dateNow, monitoringFilters.startTimeLabel);
143	  }
144	  return {
145	    startTime: monitoringFilters.startTime,
146	    endTime: monitoringFilters.endTime,
147	  };
148	}
149	
150	export function startTimeLabelToStartEndTime(
151	  dateNow: Date,
152	  startTimeLabel: START_TIME_LABEL,
153	): {
154	  startTime: string | undefined;
155	  endTime: string | undefined;
156	} {
157	  switch (startTimeLabel) {
158	    case 'LAST_HOUR':
159	      return {
160	        startTime: new Date(new Date(dateNow).setUTCHours(new Date().getUTCHours() - 1)).toISOString(),
161	        endTime: dateNow.toISOString(),
162	      };
163	    case 'LAST_24_HOURS':
164	      return {
165	        startTime: new Date(new Date(dateNow).setUTCDate(new Date().getUTCDate() - 1)).toISOString(),
166	        endTime: dateNow.toISOString(),
167	      };
168	    case 'LAST_7_DAYS':
169	      return {
170	        startTime: new Date(new Date(dateNow).setUTCDate(new Date().getUTCDate() - 7)).toISOString(),
171	        endTime: dateNow.toISOString(),
172	      };
173	    case 'LAST_30_DAYS':
174	      return {
175	        startTime: new Date(new Date(dateNow).setUTCDate(new Date().getUTCDate() - 30)).toISOString(),
176	        endTime: dateNow.toISOString(),
177	      };
178	    case 'LAST_YEAR':
179	      return {
180	        startTime: new Date(new Date(dateNow).setUTCFullYear(new Date().getUTCFullYear() - 1)).toISOString(),
181	        endTime: dateNow.toISOString(),
182	      };
183	    case 'ALL':
184	      return {
185	        startTime: undefined,
186	        endTime: dateNow.toISOString(),
187	      };
188	    default:
189	      throw new Error(`Unexpected start time label: ${startTimeLabel}`);
190	  }
