// Time range filter parameters are preserved across every tab, regardless of the tab group.
// All other query params are considered tab-specific and are dropped when navigating outside
// the applicable tab group.
export const TIME_RANGE_QUERY_PARAM_KEYS = ['startTimeLabel', 'startTime', 'endTime'];

/**
 * Computes the `search` string to use for a side nav link, given the current URL search string
 * and the tabs being navigated between.
 *
 * - When navigating between two traces-related tabs, all query params are preserved.
 * - Otherwise (any navigation involving a non-traces-related tab), only the time range params
 *   are preserved and every other tab-specific param is dropped.
 *
 * Returns `undefined` when there are no params to preserve.
 */
export const getSideNavLinkSearch = (
  currentSearch: string,
  activeTab: ExperimentPageTabName,
  targetTab: ExperimentPageTabName,
): string | undefined => {
  if (isTracesRelatedTab(activeTab) && isTracesRelatedTab(targetTab)) {
    return currentSearch || undefined;
  }

  const currentParams = new URLSearchParams(currentSearch);
  const preservedParams = new URLSearchParams();
  for (const key of TIME_RANGE_QUERY_PARAM_KEYS) {
    const value = currentParams.get(key);
    if (value !== null) {
      preservedParams.set(key, value);
    }
  }

  const search = preservedParams.toString();
  return search ? `?${search}` : undefined;
};
