3	export const isTracesRelatedTab = (tabName: ExperimentPageTabName) => {
4	  return (
5	    tabName === ExperimentPageTabName.Overview ||
6	    tabName === ExperimentPageTabName.Traces ||
7	    tabName === ExperimentPageTabName.SingleChatSession ||
8	    tabName === ExperimentPageTabName.ChatSessions
9	  );
10	};
