12	// Time range filter parameters are preserved across every tab, regardless of the tab group.
13	// All other query params are considered tab-specific and are dropped when navigating outside
14	// the applicable tab group.
15	export const TIME_RANGE_QUERY_PARAM_KEYS = ['startTimeLabel', 'startTime', 'endTime'];
16	
17	/**
18	 * Computes the `search` string to use for a side nav link, given the current URL search string
19	 * and the tabs being navigated between.
20	 *
21	 * - When navigating between two traces-related tabs, all query params are preserved.
22	 * - Otherwise (any navigation involving a non-traces-related tab), only the time range params
23	 *   are preserved and every other tab-specific param is dropped.
24	 *
25	 * Returns `undefined` when there are no params to preserve.
26	 */
27	export const getSideNavLinkSearch = (
28	  currentSearch: string,
29	  activeTab: ExperimentPageTabName | undefined,
30	  targetTab: ExperimentPageTabName,
31	): string | undefined => {
32	  if (activeTab !== undefined && isTracesRelatedTab(activeTab) && isTracesRelatedTab(targetTab)) {
33	    return currentSearch || undefined;
34	  }
35	
36	  const currentParams = new URLSearchParams(currentSearch);
37	  const preservedParams = new URLSearchParams();
38	  for (const key of TIME_RANGE_QUERY_PARAM_KEYS) {
39	    const value = currentParams.get(key);
40	    if (value !== null) {
41	      preservedParams.set(key, value);
42	    }
43	  }
44	
45	  const search = preservedParams.toString();
46	  return search ? `?${search}` : undefined;
47	};
